/**
 * Splits & IOUs (Phase 6 §4.2). Pure maths: splitting a bill to the cent (always summing to the total), balances per
 * person, settling and the payment-request message. People are names only; nothing about them leaves the device
 * except in the message the person chooses to share.
 */

export type SplitMode = 'equal' | 'amounts' | 'shares'

/** Mirrors public.splits — Migration 028. */
export interface Split {
  id: string
  user_id: string
  title: string
  total: number
  /** 'YYYY-MM-DD' */
  spent_on: string
  paid_by: 'me' | 'other'
  payer_name: string | null
  split_mode: SplitMode
  spend_entry_id: string | null
  note: string | null
  deleted_at: string | null
  created_at: string
  updated_at: string
}

/** Mirrors public.split_shares — Migration 028. */
export interface SplitShare {
  id: string
  split_id: string
  user_id: string
  person_name: string
  is_me: boolean
  amount: number
  settled_amount: number
  settled_at: string | null
  last_reminded_at: string | null
  reminders_sent: number
}

const toCents = (n: number) => Math.round(n * 100)

/**
 * Splits `total` across people.
 * - equal: everyone gets total ÷ n; leftover cents go to the first people, so R100 three ways is 33.34, 33.33, 33.33.
 * - shares: proportional to weights, largest-remainder rounding.
 * - amounts: the amounts given (must add up to the total — see amountsMismatch).
 * Every result sums to the total exactly, in cents.
 */
export function splitAmounts(total: number, mode: SplitMode, parts: number[]): number[] {
  const n = parts.length
  if (n === 0) return []
  const cents = toCents(total)
  if (mode === 'amounts') return parts.map((p) => toCents(p) / 100)
  const weights = mode === 'equal' ? parts.map(() => 1) : parts.map((w) => Math.max(0, w))
  const sum = weights.reduce((s, w) => s + w, 0)
  if (sum <= 0) return parts.map(() => 0)
  const exact = weights.map((w) => (cents * w) / sum)
  const floors = exact.map(Math.floor)
  let left = cents - floors.reduce((s, x) => s + x, 0)
  const order = exact
    .map((x, i) => ({ i, frac: x - Math.floor(x) }))
    .sort((a, b) => b.frac - a.frac || a.i - b.i)
  for (const { i } of order) {
    if (left <= 0) break
    floors[i]++
    left--
  }
  return floors.map((c) => c / 100)
}

/** For 'amounts' mode: the difference between what was typed and the total (0 = it adds up). */
export function amountsMismatch(total: number, amounts: number[]): number {
  return (toCents(total) - amounts.reduce((s, a) => s + toCents(a), 0)) / 100
}

export function outstanding(share: Pick<SplitShare, 'amount' | 'settled_amount'>): number {
  return Math.max(0, (toCents(share.amount) - toCents(share.settled_amount)) / 100)
}

export interface Balance {
  person: string
  /** They owe me (splits I paid). */
  owesMe: number
  /** I owe them (splits they paid). */
  iOwe: number
  splitIds: string[]
}

/** Open balances per person, plus totals ("Owed to you R 900 · You owe R 150"). */
export function balances(splits: Split[], shares: SplitShare[]): { people: Balance[]; owedToMe: number; iOwe: number } {
  const byId = new Map(splits.filter((s) => !s.deleted_at).map((s) => [s.id, s]))
  const people = new Map<string, Balance>()
  let owedToMe = 0
  let iOwe = 0
  for (const sh of shares) {
    const split = byId.get(sh.split_id)
    if (!split) continue
    const open = outstanding(sh)
    if (open <= 0) continue
    if (split.paid_by === 'me' && !sh.is_me) {
      const key = sh.person_name.trim()
      const b = people.get(key.toLowerCase()) ?? { person: key, owesMe: 0, iOwe: 0, splitIds: [] }
      b.owesMe += open
      b.splitIds.push(split.id)
      people.set(key.toLowerCase(), b)
      owedToMe += open
    } else if (split.paid_by === 'other' && sh.is_me) {
      const key = (split.payer_name ?? 'Someone').trim()
      const b = people.get(key.toLowerCase()) ?? { person: key, owesMe: 0, iOwe: 0, splitIds: [] }
      b.iOwe += open
      b.splitIds.push(split.id)
      people.set(key.toLowerCase(), b)
      iOwe += open
    }
  }
  const round = (n: number) => Math.round(n * 100) / 100
  return {
    people: [...people.values()].map((b) => ({ ...b, owesMe: round(b.owesMe), iOwe: round(b.iOwe) })).sort((a, b) => b.owesMe + b.iOwe - (a.owesMe + a.iOwe)),
    owedToMe: round(owedToMe),
    iOwe: round(iOwe),
  }
}

/** Settling `amount` (part or full) against a share. Never more than what's outstanding. */
export function settle(share: Pick<SplitShare, 'amount' | 'settled_amount'>, amount: number, now = new Date()): { settled_amount: number; settled_at: string | null; applied: number } {
  const applied = Math.min(outstanding(share), Math.max(0, Math.round(amount * 100) / 100))
  const settled_amount = (toCents(share.settled_amount) + toCents(applied)) / 100
  return { settled_amount, settled_at: settled_amount >= Number(share.amount) ? now.toISOString() : null, applied }
}

/** A split is settled once every other person's share is paid up. */
export function isSettled(split: Split, shares: SplitShare[]): boolean {
  return shares.filter((s) => s.split_id === split.id && !s.is_me).every((s) => outstanding(s) === 0) &&
    !(split.paid_by === 'other' && shares.some((s) => s.split_id === split.id && s.is_me && outstanding(s) > 0))
}

/** "Hi Thabo — your share for Airbnb is R 300. PayShap: 0821234567@capitec. Thanks!" */
export function requestMessage(person: string, title: string, amountText: string, shapId?: string | null): string {
  const first = person.trim().split(/\s+/)[0] || person
  return `Hi ${first} — your share for ${title} is ${amountText}.${shapId ? ` PayShap: ${shapId}.` : ''} Thanks!`
}

/** People's names used before, most frequent first (autocomplete). */
export function knownPeople(shares: SplitShare[], limit = 20): string[] {
  const counts = new Map<string, { name: string; n: number }>()
  for (const s of shares) {
    if (s.is_me) continue
    const k = s.person_name.trim().toLowerCase()
    const c = counts.get(k) ?? { name: s.person_name.trim(), n: 0 }
    c.n++
    counts.set(k, c)
  }
  return [...counts.values()].sort((a, b) => b.n - a.n).slice(0, limit).map((c) => c.name)
}

export interface SplitNotice {
  kind: 'split'
  title: string
  body: string
  link: string
  dedupe_key: string
  share_id: string
}

/**
 * Server-side reminders (notify-daily): a share owed to me, unsettled for more than 7 days, at most weekly and at most
 * three times (reminders_sent).
 */
export function splitReminders(splits: Split[], shares: SplitShare[], today: Date, fmt: (n: number) => string): SplitNotice[] {
  const byId = new Map(splits.filter((s) => !s.deleted_at && s.paid_by === 'me').map((s) => [s.id, s]))
  const out: SplitNotice[] = []
  for (const sh of shares) {
    const split = byId.get(sh.split_id)
    if (!split || sh.is_me || outstanding(sh) <= 0 || sh.reminders_sent >= 3) continue
    const age = (today.getTime() - new Date(`${split.spent_on}T00:00:00`).getTime()) / 86_400_000
    if (age <= 7) continue
    if (sh.last_reminded_at && today.getTime() - new Date(sh.last_reminded_at).getTime() < 7 * 86_400_000) continue
    out.push({
      kind: 'split',
      title: `${sh.person_name} still owes you`,
      body: `${sh.person_name} still owes ${fmt(outstanding(sh))} for ${split.title}.`,
      link: '/splits',
      dedupe_key: `split:${sh.id}:${sh.reminders_sent + 1}`,
      share_id: sh.id,
    })
  }
  return out
}
